for (var order : orders) {
    producer.send(new ProducerRecord<>("orders", order.id(), json),
        (meta, ex) -> {
            if (ex != null) {
                log.error("send failed key={}", order.id(), ex);
                failureCounter.increment();
                return;
            }
            log.debug("sent to {}-{}", meta.partition(), meta.offset());
        });
}
